-- Joining & Drop (2026-10-17): the joining record (one per application, with the drop and the client replacement decision on the same row), its history, and the notice log.
-- Raw-SQL tables, no Prisma model; the app also creates them itself with IF NOT EXISTS (src/joindrop/schema.js), which also adds any later column with a guarded ALTER.
-- Every time column is TEXT (an ISO string). No column is added to any existing table.
CREATE TABLE IF NOT EXISTS "JoiningRecord" ( "id" TEXT NOT NULL PRIMARY KEY, "applicationId" TEXT NOT NULL, "candidateId" TEXT NOT NULL, "candidateName" TEXT, "requirementId" TEXT, "jobTitle" TEXT, "jobCode" TEXT, "clientId" TEXT, "clientName" TEXT, "department" TEXT, "hiringType" TEXT, "status" TEXT NOT NULL DEFAULT 'Joined', "joinedOn" TEXT, "location" TEXT, "designation" TEXT, "offeredCtc" REAL, "employmentType" TEXT, "reportingPerson" TEXT, "reportingContact" TEXT, "recruiterUserId" TEXT, "recruiterName" TEXT, "tlUserId" TEXT, "tlName" TEXT, "bdeUserId" TEXT, "bdeName" TEXT, "seat" TEXT, "guaranteeDays" INTEGER, "guaranteeStartOn" TEXT, "guaranteeEndsOn" TEXT, "guaranteeSource" TEXT, "replacementTaskId" TEXT, "replacementTaskState" TEXT, "replacementTaskCancelReason" TEXT, "replacementTaskCancelledByName" TEXT, "replacementTaskCancelledAt" TEXT, "notes" TEXT, "recordedById" TEXT, "recordedByName" TEXT, "recordedByRole" TEXT, "recordedVia" TEXT, "backfilled" INTEGER NOT NULL DEFAULT 0, "droppedOn" TEXT, "lastWorkingDay" TEXT, "dropReason" TEXT, "dropReasonDetail" TEXT, "dropReportedById" TEXT, "dropReportedByName" TEXT, "dropReportedByRole" TEXT, "dropReportedFrom" TEXT, "dropReportedAt" TEXT, "dropWithinGuarantee" INTEGER, "dropDaysSinceJoining" INTEGER, "dropAfterIncentive" INTEGER NOT NULL DEFAULT 0, "replacementDecision" TEXT, "replacementComment" TEXT, "replacementExpectedOn" TEXT, "replacementProfileNotes" TEXT, "replacementDecidedAt" TEXT, "replacementDecidedById" TEXT, "replacementDecidedByName" TEXT, "replacementOnBehalf" INTEGER NOT NULL DEFAULT 0, "replacementStatus" TEXT, "replacementApplicationId" TEXT, "replacementLinkedAt" TEXT, "createdAt" TEXT NOT NULL, "updatedAt" TEXT NOT NULL );
CREATE UNIQUE INDEX IF NOT EXISTS "JoiningRecord_application" ON "JoiningRecord"("applicationId");
CREATE INDEX IF NOT EXISTS "JoiningRecord_candidate" ON "JoiningRecord"("candidateId");
CREATE INDEX IF NOT EXISTS "JoiningRecord_client" ON "JoiningRecord"("clientId", "status");
CREATE INDEX IF NOT EXISTS "JoiningRecord_joined" ON "JoiningRecord"("joinedOn");
CREATE INDEX IF NOT EXISTS "JoiningRecord_status" ON "JoiningRecord"("status", "droppedOn");
CREATE TABLE IF NOT EXISTS "JoiningEvent" ( "id" TEXT NOT NULL PRIMARY KEY, "recordId" TEXT NOT NULL, "applicationId" TEXT, "candidateId" TEXT, "at" TEXT NOT NULL, "kind" TEXT NOT NULL, "byId" TEXT, "byName" TEXT, "byRole" TEXT, "fromWhere" TEXT, "onBehalf" INTEGER NOT NULL DEFAULT 0, "summary" TEXT NOT NULL, "oldValue" TEXT, "newValue" TEXT, "note" TEXT );
CREATE INDEX IF NOT EXISTS "JoiningEvent_record" ON "JoiningEvent"("recordId", "at");
CREATE INDEX IF NOT EXISTS "JoiningEvent_candidate" ON "JoiningEvent"("candidateId", "at");
CREATE TABLE IF NOT EXISTS "JoinDropNotice" ( "id" TEXT NOT NULL PRIMARY KEY, "recordId" TEXT NOT NULL, "eventId" TEXT NOT NULL, "party" TEXT NOT NULL, "channel" TEXT NOT NULL, "recipientKey" TEXT NOT NULL, "recipientName" TEXT, "recipientEmail" TEXT, "userId" TEXT, "status" TEXT, "detail" TEXT, "createdAt" TEXT NOT NULL );
CREATE UNIQUE INDEX IF NOT EXISTS "JoinDropNotice_once" ON "JoinDropNotice"("eventId", "channel", "recipientKey");
CREATE INDEX IF NOT EXISTS "JoinDropNotice_record" ON "JoinDropNotice"("recordId", "createdAt");
